			    app.lookup("dmSave").setValue("RCMDTN_SHELTR_NO", grdRowData.getValue("RCMDTN_SHELTR_NO"));
			    app.lookup("dmSave").setValue("RCMDTN_SHELTR_NM", grdRowData.getValue("RCMDTN_SHELTR_NM"));
			    app.lookup("dmSave").setValue("RCMDTN_YMD", grdRowData.getValue("RCMDTN_YMD"));
			    app.lookup("dmSave").setValue("PENSN_GIVE_STTS_BGNG_YM", grdRowData.getValue("PENSN_GIVE_STTS_BGNG_YM"));
			    app.lookup("dmSave").setValue("MM_PENSN_GIVE_AMT", grdRowData.getValue("MM_PENSN_GIVE_AMT"));
			    app.lookup("dmSave").setValue("PENSN_GIVE_CHG_LCGOV_NO", grdRowData.getValue("PENSN_GIVE_CHG_LCGOV_NO"));
			    app.lookup("dmSave").setValue("PENSN_GIVE_CHG_LCGOV_NM", grdRowData.getValue("PENSN_GIVE_CHG_LCGOV_NM"));
			    app.lookup("dmSave").setValue("PENSN_GIVE_CHG_BFE_LCGOV_NO", grdRowData.getValue("PENSN_GIVE_CHG_BFE_LCGOV_NO"));
			    app.lookup("dmSave").setValue("PENSN_GIVE_CHG_BFE_LCGOV_NM", grdRowData.getValue("PENSN_GIVE_CHG_BFE_LCGOV_NM"));
			    app.lookup("dmSave").setValue("STTS_OCRN_CS_SE_CD", grdRowData.getValue("STTS_OCRN_CS_SE_CD"));
			    app.lookup("dmSave").setValue("STTS_OCRN_CS_CN", grdRowData.getValue("STTS_OCRN_CS_CN"));
