			/*
			 * 사용자 정의 컨트롤에서 save 이벤트 발생 시 호출.
			 * 저장 클릭 이벤트
			 */
			function onComBtnGrid1Save(e){
			    var comBtnGrid1 = e.control;
			    
			    if(app.lookup("dsPensnGiveDcsnList").isModified()){
			        
			        var editStatus = false;
			        
			        // 수정된 DataSet의 Row index
			        var modifiedKeyIndex = app.lookup("dsPensnGiveDcsnList").getRowStatedIndices(cpr.data.tabledata.RowState.UPDATED);        
			        if(!ValueUtil.isNull(modifiedKeyIndex)){
			            
			            // 현재 수정된 내용에서 날짜, 상태코드, 순번을 가져와서 필터 값으로 저장한다
			            for(var i=0; i<modifiedKeyIndex.length; i++){
			                
			                // 수정된 값
			                var editYmd = app.lookup("dsPensnGiveDcsnList").getRowData(modifiedKeyIndex[i]).PENSN_GIVE_STTS_OCRN_YMD;
			                var editSeq = app.lookup("dsPensnGiveDcsnList").getRowData(modifiedKeyIndex[i]).TASKWK_OCRN_SQNCE;
			                
			                // 필터 조건
			                var condition = "PENSN_GIVE_STTS_OCRN_YMD == " + "'" + editYmd + "'" + " && TASKWK_OCRN_SQNCE == " + "'" + editSeq + "'"
			                
			                // 수정된 row 값의 필터 조건으로 해당 row에 동일한 값이 1개 이상 나오면 중복이 발생한 것
			                if(app.lookup("dsPensnGiveDcsnList").getConditionalRowCount(condition) > 1){
			                    
			                    util.Msg.alert(app, "상태 발생일자 및 순서의 값이 중복인지 확인해주세요.");
			                    return false;

			                }else {
			                    // 수정 가능 상태로 변경
			                    editStatus = true;
			                    
			                }

			            }
			            
			            // 수정 가능 상태일 때, 메세지 출력                        
			            if(editStatus == true){
			                
			                util.Msg.confirm(app, "상태발생순서를 저장하시겠습니까?", null, function(){
			    
			                    // 수정된 DataSet 전달 후 순번 Update 호출
			                    util.Submit.send(app, "subSavePensnGiveDcsnSeq", function(pbSuccess){
			                        
			                        if(pbSuccess) {
			                
			                            // 화면 재처리
			                            doList();
			                        
			                        }
			    
			                    });
			                    
			                }, function(){
			                     /*취소버튼 콜백*/            
			                }, "알림", null, true);
			                
			            }

			        }

			    }else{
			        util.Msg.alert(app, "수정된 상태발생순서가 없습니다.");
			        return false;
			    }
			    
			}

